79	    ) -> Result<ListMemoriesResponse, MemoriesBackendError> {
80	        let max_results = request.max_results.min(MAX_LIST_RESULTS);
81	        let start = self.resolve_scoped_path(request.path.as_deref())?;
82	        let start_index = match request.cursor.as_deref() {
83	            Some(cursor) => cursor.parse::<usize>().map_err(|_| {
84	                MemoriesBackendError::invalid_cursor(cursor, "must be a non-negative integer")
85	            })?,
86	            None => 0,
87	        };
88	        let Some(metadata) = Self::metadata_or_none(&start).await? else {
89	            return Ok(ListMemoriesResponse {
90	                path: request.path,
91	                entries: Vec::new(),
92	                next_cursor: None,
93	                truncated: false,
94	            });
95	        };
96	        reject_symlink(&display_relative_path(&self.root, &start), &metadata)?;
97	
98	        let mut entries = if metadata.is_file() {
99	            vec![MemoryEntry {
100	                path: display_relative_path(&self.root, &start),
101	                entry_type: MemoryEntryType::File,
102	            }]
103	        } else if metadata.is_dir() {
104	            let mut entries = Vec::new();
105	            for path in read_sorted_dir_paths(&start).await? {
106	                let Some(metadata) = Self::metadata_or_none(&path).await? else {
107	                    continue;
108	                };
109	                if metadata.file_type().is_symlink() {
110	                    continue;
111	                }
112	
113	                let entry_type = if metadata.is_dir() {
114	                    MemoryEntryType::Directory
115	                } else if metadata.is_file() {
116	                    MemoryEntryType::File
117	                } else {
118	                    continue;
119	                };
120	                entries.push(MemoryEntry {
121	                    path: display_relative_path(&self.root, &path),
122	                    entry_type,
123	                });
124	            }
125	            entries
126	        } else {
127	            Vec::new()
128	        };
129	        if start_index > entries.len() {
130	            return Err(MemoriesBackendError::invalid_cursor(
131	                start_index.to_string(),
132	                "exceeds result count",
133	            ));
134	        }
135	
136	        let end_index = start_index.saturating_add(max_results).min(entries.len());
137	        let next_cursor = (end_index < entries.len()).then(|| end_index.to_string());
138	        let truncated = next_cursor.is_some();
139	        Ok(ListMemoriesResponse {
140	            path: request.path,
141	            entries: entries.drain(start_index..end_index).collect(),
142	            next_cursor,
143	            truncated,
144	        })
145	    }
