136	                json!(
137	                    self.backend
138	                        .read(ReadMemoryRequest {
139	                            path: args.path,
140	                            line_offset: args.line_offset.unwrap_or(1),
141	                            max_lines: args.max_lines,
142	                            max_tokens: DEFAULT_READ_MAX_TOKENS,
143	                        })
144	                        .await
145	                        .map_err(backend_error_to_mcp)?
146	                )
147	            }
