149	                let args: SearchArgs = parse_args(value)?;
150	                let request = args.into_request();
151	                json!(
152	                    self.backend
153	                        .search(request)
154	                        .await
155	                        .map_err(backend_error_to_mcp)?
156	                )
157	            }
158	            other => {
159	                return Err(McpError::invalid_params(
160	                    format!("unknown tool: {other}"),
161	                    None,
162	                ));
163	            }
164	        };
165	
166	        Ok(CallToolResult {
167	            content: vec![Content::text(structured_content.to_string())],
168	            structured_content: Some(structured_content),
169	            is_error: Some(false),
170	            meta: None,
171	        })
172	    }
